const pdevRelated=[{href:"portugal.html",kicker:"National setting",label:"Portugal and the Lusophone Empire"},{href:"antonio-salazar.html",kicker:"Political ruler",label:"António de Oliveira Salazar"},{href:"iberian-pact.html",kicker:"Peninsular framework",label:"Iberian Pact"},{href:"latin-bloc.html",kicker:"Later regional system",label:"Latin Bloc"}];
const pflag={src:"assets/flags/portugal.svg",alt:"Flag of Portugal",caption:"Portuguese national flag"};
function pd(d){return{title:d.title,category:d.category||"Portugal",eyebrow:d.eyebrow,infoboxKicker:d.infoboxKicker,infoboxTitle:d.infoboxTitle||d.title,lead:d.lead,canon:d.canon,sections:d.sections,related:d.related||pdevRelated,sources:d.sources||pdevSources,categories:d.categories||[d.title,"Portugal","Estado Novo"],facts:d.facts,flag:d.flag,landscape:d.landscape};}
